<script setup lang="ts">import {computed,ref} from 'vue';import * as api from '../api/runs';import {useResource} from '../hooks/useResource';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import EmptyState from '../components/common/EmptyState.vue';import SurveyMap from '../components/SurveyMap.vue';import CoverageSummary from '../components/CoverageSummary.vue';import GainSteps from '../components/GainSteps.vue';import {percent} from '../utils/format';const {data,error}=useResource(api.list,[]);const selected=ref(sessionStorage.getItem('coverage-selected-run')||'run-baseline');const run=computed(()=>data.value.find(r=>r.id===selected.value)||data.value[0]);</script><template><PageTitle chapter="05" title="覆盖的收益，也有取舍" description="检查每一步新增覆盖与移除后的损失。仍未覆盖的样点，是下一轮现场讨论的起点。"/><Notice :error="error"/><template v-if="run"><div class="toolbar"><label>计算记录<select v-model="selected" aria-label="计算记录"><option v-for="r in data" :key="r.id" :value="r.id">{{r.id}} · {{r.status}}</option></select></label><StatusBadge :status="run.status"/></div><template v-if="run.status==='completed'"><CoverageSummary :result="run.result"/><div class="map-layout"><SurveyMap :result="run.result"/><section class="map-sidebar"><p class="eyebrow">逐步选点 / MARGINAL GAIN</p><h2>覆盖如何累积</h2><GainSteps :result="run.result"/></section></div><section class="paper table-scroll"><h2>逐点移除敏感性</h2><table><thead><tr><th>移除的补给点</th><th>独有覆盖权重</th><th>移除后总覆盖率</th></tr></thead><tbody><tr v-for="s in run.result.sensitivity" :key="s.candidate_id"><td>{{s.name}}</td><td>{{s.unique_weight}}</td><td>{{percent(s.coverage_rate_without)}}</td></tr></tbody></table></section><aside class="method-note"><h3>模型口径与边界</h3><p v-for="x in run.result.limitations" :key="x">{{x}}</p><small>输入校验 SHA256：{{run.result.checksum}}</small></aside></template><section v-else class="paper"><p>{{run.status==='failed'?run.error:'后台worker正在计算距离矩阵与加权覆盖，每3秒刷新。'}}</p></section></template><EmptyState v-else text="前往预算推演页创建并运行一个方案。"/></template>
